import { defineDriver, DriverError, retryableStatus } from "@sanoma-ai/workflows";
import { z } from "zod";
import { exaOps } from "./connector.ts";
// Generated by `pnpm run generate` (openapi-ts.config.ts); never edited by hand.
import { client as generated } from "./generated/client.gen.ts";
import { createClient } from "./generated/client/index.ts";
import { answer, findSimilar, getContents, search } from "./generated/index.ts";

export interface ExaDriverOptions {
  /** How long one request may take before it fails, retryable. Default 30 seconds: a deep search or an answer takes several. */
  timeoutMs?: number;
}

/** The environment variable the driver reads, on every call. */
const env = z.object({
  EXA_API_KEY: z.string().describe("an API key, from the API Keys page of Exa's dashboard"),
});

/** Exa's error body: `{ requestId, error, tag }` (https://exa.ai/docs/reference/error-codes). */
const errorBody = z
  .object({ error: z.string().optional().catch(undefined), tag: z.string().optional().catch(undefined) })
  .catch({});

/**
 * The DriverError for a request that failed. The client hands its error interceptor what went
 * wrong, the response once Exa answered, and the request once it was built.
 */
function failure(op: string, timeoutMs: number) {
  return (error: unknown, response: Response | undefined, request: Request | undefined): DriverError => {
    if (!request) {
      return new DriverError(`exa: ${op} could not build its request`, { retryable: false, cause: error });
    }
    if (!response) {
      // No reply at all (the timeout, a dropped connection): the call may be tried again.
      const timedOut = error instanceof Error && error.name === "TimeoutError";
      return new DriverError(`exa: ${op} ${timedOut ? `timed out after ${timeoutMs} ms` : "got no reply"}`, {
        retryable: true,
        cause: error,
      });
    }
    const { ok, status, statusText } = response;
    // A body that could not be read (cut off, or the timeout fired while reading it) leaves the
    // status to decide; a 2xx whose body is not JSON is no answer to retry.
    const cutOff = error instanceof Error && !(error instanceof SyntaxError);
    if (ok) {
      return new DriverError(
        `exa: ${op} replied ${status} with ${cutOff ? "a body cut off" : "a body that is not JSON"}`,
        { retryable: cutOff, status, cause: error },
      );
    }
    const { error: message, tag } = cutOff ? {} : errorBody.parse(error);
    // A 429 (rate limit) and a 5xx (overloaded, timed out) pass; 402 (credits or budget spent) does not in a retry's wait.
    return new DriverError(`exa: ${op} failed (${status}): ${message ?? statusText}`, {
      retryable: retryableStatus(status),
      status,
      ...(tag === undefined ? {} : { vendorCode: tag }),
    });
  };
}

/** A page in a reply: the spec leaves its `id` and `url` optional. */
type Page = { id?: string; url?: string };

/** The pages of a reply, each with its `id` and `url`: a 200 without them (a proxy answering instead) is no answer. */
function pagesOf<T extends Page>(
  op: string,
  pages: T[] | undefined,
  response: Response,
): (T & { id: string; url: string })[] {
  if (Array.isArray(pages) && pages.every((p) => typeof p?.id === "string" && typeof p.url === "string")) {
    return pages as (T & { id: string; url: string })[];
  }
  throw new DriverError(`exa: ${op} replied ${response.status} without its pages`, {
    retryable: false,
    status: response.status,
  });
}

/**
 * Calls Exa's search, contents, find-similar and answer endpoints with the key in `EXA_API_KEY`,
 * read on every call. Each operation only reads, so a retried call costs credits again and
 * changes nothing.
 */
export function exaDriver(options: ExaDriverOptions = {}) {
  const timeoutMs = options.timeoutMs ?? 30_000;

  function client(op: string) {
    const key = process.env.EXA_API_KEY;
    if (!key) throw new DriverError("exa: EXA_API_KEY is not set", { retryable: false });
    // The generated client's config (the spec's server, throwOnError), with this call's key in `x-api-key`.
    const api = createClient({
      ...generated.getConfig(),
      auth: key,
      fetch: (input, init) => fetch(input, { ...init, signal: AbortSignal.timeout(timeoutMs) }),
    });
    api.interceptors.error.use(failure(op, timeoutMs));
    return api;
  }

  return defineDriver(
    exaOps,
    {
      web: {
        search: async (body) => {
          const { data, response } = await search({ client: client("web.search"), body });
          return { results: pagesOf("web.search", data?.results, response) };
        },
        getContents: async (body) => {
          const { data, response } = await getContents({ client: client("web.getContents"), body });
          // The spec leaves each status's fields optional; the runtime checks the reply against the operation's output.
          const statuses = (data.statuses ?? []) as z.infer<typeof exaOps.web.getContents.output>["statuses"];
          return { results: pagesOf("web.getContents", data.results, response), statuses };
        },
        findSimilar: async (body) => {
          const { data, response } = await findSimilar({ client: client("web.findSimilar"), body });
          return { results: pagesOf("web.findSimilar", data?.results, response) };
        },
        answer: async (body) => {
          const { data, response } = await answer({ client: client("web.answer"), body });
          // A string unless the request sends an `outputSchema`, which this one never does.
          if (typeof data?.answer !== "string") {
            throw new DriverError(`exa: web.answer replied ${response.status} without an answer`, {
              retryable: false,
              status: response.status,
            });
          }
          return { answer: data.answer, citations: pagesOf("web.answer", data.citations ?? [], response) };
        },
      },
    },
    { env },
  );
}
